pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller, uint256 callerBalance) public {
        vm.assume(caller != address(0));
        callerBalance = bound(callerBalance, 0, 1 ether);
        vm.deal(caller, callerBalance);

        bool ok;
        vm.startPrank(caller);
        try c.play{value: 11}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(ok == false);
    }
}
